# 路由器 radvd.conf 关键片段
interface eth1 {
  AdvSendAdvert on;
  prefix 2001:db8:10::/64 { AdvOnLink on; AdvAutonomous on; };  # SLAAC 前缀
  AdvManagedFlag off;   # 改 on 即切有状态
  AdvOtherConfigFlag on;
}
# 终端: ip -6 addr show eth0 观察
#   scope global 地址是否自动出现(SLAAC 生效)
#   "managed" / "other" 标志位与 radvd 是否一致
#   tcpdump -i eth0 icmp6 过滤 type 134(RA)/135(NS)/136(NA) 观察 DAD 过程

options {
  recursion yes;                       # 开递归(面向内网)
  allow-recursion { 10.0.0.0/8; };     # 只对内网开放, 防止沦为公网放大器
  forwarders { 223.5.5.5; };           # 转发器
  dnssec-validation auto;
};
